@router.post(PAGE)
def add_room(
    request: Request,
    session: DbSession,
    person: CurrentPerson,
    name: FormText = "",
    capacity: FormText = "",
) -> Response:
    try:
        room = service.add_room(session, person, name, capacity)
    except InvalidRoom as exc:
        if _is_htmx(request):
            return _fragment(
                request,
                "rooms/_add_form.html",
                status_code=422,
                errors=exc.errors,
                values=exc.values,
            )
        return _page(
            request,
            session,
            person,
            status_code=422,
            add_errors=exc.errors,
            add_values=exc.values,
        )
    if _is_htmx(request):
        # A fresh form, with the table (now holding the room, in name order) out of band.
        return _fragment(
            request,
            "rooms/_add_form.html",
            notice=_notice("added", room),
            errors=[],
            values=None,
            person=person,
            rooms=service.list_rooms(session, person),
            table_oob=True,
        )
    return _redirect("added", room)


